@Bean
  public FilterRegistrationBean<DatabaseHealthFilter> disableDatabaseHealthServletFilter(
      DatabaseHealthFilter filter) {
    FilterRegistrationBean<DatabaseHealthFilter> registration =
        new FilterRegistrationBean<>(filter);
    registration.setEnabled(false);
    return registration;
  }

@Override
  public void configure(final AuthorizationServerSecurityConfigurer oauthServer) {
    oauthServer.passwordEncoder(this.passwordEncoder).tokenKeyAccess("permitAll()")
        .checkTokenAccess("isAuthenticated()");
  }

@Bean
  public FilterRegistrationBean<BlockedUserFilter> disableBlockedUserServletFilter(
      BlockedUserFilter filter) {
    FilterRegistrationBean<BlockedUserFilter> registration = new FilterRegistrationBean<>(filter);
    registration.setEnabled(false);
    return registration;
  }

