@GetMapping("/resend-email-verification")
    @Operation(
        summary = "Resend e-mail verification endpoint",
        security = @SecurityRequirement(name = SECURITY_SCHEME_NAME),
        responses = {
            @ApiResponse(
                responseCode = "200",
                description = "Successful operation",
                content = @Content(
                    mediaType = "application/json",
                    schema = @Schema(implementation = SuccessResponse.class)
                )
            ),
            @ApiResponse(
                responseCode = "400",
                description = "Bad request",
                content = @Content(
                    mediaType = MediaType.APPLICATION_JSON_VALUE,
                    schema = @Schema(implementation = ErrorResponse.class)
                )
            ),
            @ApiResponse(
                responseCode = "401",
                description = "Bad credentials",
                content = @Content(
                    mediaType = MediaType.APPLICATION_JSON_VALUE,
                    schema = @Schema(implementation = ErrorResponse.class)
                )
            )
        }
    )
    public ResponseEntity<SuccessResponse> resendEmailVerificationMail() {
        userService.resendEmailVerificationMail();

        return ResponseEntity.ok(SuccessResponse.builder()
            .message(messageSourceService.get("verification_email_sent"))
            .build());
    }

import { useState } from "react";
import { Form, Formik } from "formik";
import * as Yup from "yup";
import InputAdmin from "../inputs/InputAdmin";
import axios from "axios";

const CreateCategory = ({ setCategories }: any) => {
    const [name, setName] = useState();
    const validate = Yup.object({
        name: Yup.string()
        .required("Category name is required.")
        .min(3,"Category name must be between 3 and 32 characters.")
        .max(32,"Category name must be between 3 and 32 characters.")
        .matches(/^[aA-zZ]/,"Numbers and special characters are not allowed."),
    });

    const submitHandler = async () => {
        try {
            const { data } = await axios.post("/api/admin/category",{ name });
            console.log(data)
            setCategories(data.categories)
        } catch (error: any) {
            console.log(error.response.data.message)
        }
    };
    const handleChange = (e: any) => {
        setName(e.target.value)
    }
    return (
        <div className="mt-4">
            <div className="flex p-2 border-b pb-1 font-semibold">
                Create a Category
            </div>
            <Formik
                enableReinitialize
                initialValues={{ name }}
                validationSchema={validate}
                onSubmit={() => submitHandler()}
            >
                {(form) => (
                    <Form className="flex-1 flex-col">
                        <InputAdmin
                            type="text"
                            name="name"
                            label="Category"
                            placeholder="Category Name"
                            icon="category"
                            onChange={handleChange}
                        />
                        <button className="mt-4 bg-green-500 py-2 px-4 rounded mt-2 text-white">
                            add a category
                        </button>
                    </Form>
                )}
            </Formik>

        </div>
    );
};
